userscript.function:

callFunction('p', 'childScreenReady', [{
    name:'SINGLE_SIGNER',
    id: $sObject.aliasCode,
    fn:{
        doOpenDocument:doOpenDocument,
        doClear:doClear,
        doValidate:doValidate,
        onScreenDataUpdate:onScreenDataUpdate
    }
}])


            formObj.setValue("CONT_TYPE", "E");


			// init -> onReady -> doOpenDocument 통해 $share가 초기화되기 전단계라 오류발생.
        	// initForm에 구현은했으나, initForm에서 작동하는게 맞는가?

            if($share.config.data['SIGNER'].length == 0) {
                const defaultSigner = getSignerCurrentSession();
                if(defaultSigner == undefined) {
                    // 현재 사용자($.{ID})에 대한 계약자 정보 조회에 실패했습니다.<br>관리자에게 문의해 계약자 등록을 진행해주세요.
                    Alert(sUtils.string.dataReplacer(sUtils.cache.text.get('ECT_205_E.MESSAGE_FAILED_ADD_CURRENT_SIGNER'), Sepoa.info), () => {
                        callFunction(['p', 'p'], 'changeView', [{view:'LIST'}]);
                    });
                } else {
                    addSigner(defaultSigner);
                }
            }


            if (name == 'SIGNER_SEARCH') {

				const options = {
					url: window.CONTEXT_NAME + '/EmployeeContract/setForm/EmployeeContractsetFormSignerPopup.sux',
					params: {
						CONT_TYPE: formObj.getValue('CONT_TYPE'),
						SINGLE_SIGN : 'Y', // 비정형서식일때만 포함되는 구분값
						callback: (data) => {

								if(data.SIGNER_ID == Sepoa.info.ID){
									Alert(Sepoa.cache.text.get("ECT_205_G.CHECK_ID")); // 자기 자신을 서명대상자로 지정할 수 없습니다.
									return false;
								}

								for(let key in data){
									formObj.setValue(key, data[key]);
								}

								const mergeData = parseSignerData(data)
								$share.config.data.SIGNER_GROUP = [];
								$share.config.data.SIGNER_GROUP.push(mergeData);
						}
					},
					width: SUX.getModuleTop().outerWidth * 0.6,
					height: SUX.getModuleTop().outerHeight * 0.5,
					title: sUtils.cache.text.get('ECT_205_E_POPUP.TITLE') // '계약자 선택'
				};

				sUtils.popup.modal(options);
			}


			 if(name == 'CONT_TO') {
                $share.config.data.CONT_TO = sUtils.date.toString(value).replace(/\D/g, '')
            } else if(name == 'CONT_FROM') {
                $share.config.data.CONT_FROM = sUtils.date.toString(value).replace(/\D/g, '')
            }

            callFunction('p', 'onChangeData', ['SINGLE_SIGNER', name, value]);


			$share.config = config;

            if(!config?.data) {
                config.data = {};
            }

            initForm();

            return true;
            // 초기화 이후 문서를 불러오는 코드 작성필요


    if(!formObj.validate()){
		Alert(Sepoa.cache.text.get("ECT_205_G.MSG6")); // 입력되지않은 필수값이 존재합니다. 
		return false ;
	}

    if($share.config.data['SIGNER_GROUP'] === undefined || $share.config.data['SIGNER_GROUP'].length <= 0) {
        const msg = sUtils.cache.text.get('ECT_205_E.MESSAGE_REQUIRE_MIN_SIGNER');
        Alert(sUtils.string.dataReplacer(msg, {MIN_SIGNER : 1}));

        return false;
    }

	return true;


let myCompany;
const service = 'sepoa.svc.ct.ECT_205_E_POPUP';
const companySO = doServiceAjax(service, 'CONNECTION', 'doQueryCompany', {}, null, false);
if(companySO.status == '1') {
    const companyList = new SepoaFormater(companySO.result[0]).getArrayMap();
    if(companyList.length == 0) {
        // 현재 사용자에 대한 계약자 정보 조회에 실패했습니다.<br>관리자에게 문의해 계약자 등록을 진행해주세요.
        return;
    }

    myCompany = companyList.find(e => e['SIGNER_COMPANY_CODE'] == Sepoa.info['COMPANY_CODE']);
    if(myCompany === undefined) {
        return;
    }
}

let targetManager;
const managerParams = {
    ...myCompany,
    F_KEYWORD : Sepoa.info['ID']
};
const managerSO = doServiceAjax(service, 'CONNECTION', 'doQuerySigner', managerParams, null, false);
if (managerSO.status == '1') {
    const managerList = new SepoaFormater(managerSO.result[0]).getArrayMap();
    if(managerList.length <= 0) {
        return;
    }

    targetManager = managerList.find(e => e['SIGNER_ID'] == Sepoa.info['ID']);
    if(targetManager === undefined) {
        return;
    }
}

return {
    ...myCompany,
    ...targetManager,
    SEQ : '1',
    CATEGORY : 'COMPANY'
};


if (!$share.config.data) {
	return;
}

$share.config.data.SIGNER = [];

let targetList;
if (Array.isArray(data)) {
	targetList = data;
} else {
	targetList = [data];
}

for (let signer of targetList) {
	if (signer.SIGNER_ID == '') {
		return;
	}

	const mergeData = parseSignerData(signer);
	$share.config.data.SIGNER.push(mergeData);
}



let delKeyTarget = ['gr_id', 'SELECTED'];

for (var i in delKeyTarget) {
	delete data[delKeyTarget[i]]
}

const result = {
	SIGNER_COMPANY_CODE: data.SIGNER_COMPANY_CODE,
	SIGNER_COMPANY_NAME: data.SIGNER_COMPANY_NAME,
	SIGNER_ID: data.SIGNER_ID,
	SIGNER_NAME: data.SIGNER_NAME,
	SIGNER_EMAIL: data.SIGNER_EMAIL,
	SIGNER_PHONE: data.SIGNER_PHONE,
	SIGNER_COMPANY_OWNER: data.SIGNER_COMPANY_OWNER,
	SIGNER_COMPANY_ADDR: data.SIGNER_COMPANY_ADDR,
	SIGN_KEY: data.IRS_NO
};

return result;
